from pathlib import Path
import html,json,csv
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'output/briefing';OUT.mkdir(parents=True,exist_ok=True)
Q=[]
def add(s,t,a,d,w,r,p=False,k=''):
 Q.append(dict(section=s,title=t,short=a,deep=d,where=w,source=r,priority=p,terms=k))
P='outputs/performance_evaluation_report.md';F='outputs/fairness_evaluation_report.md';E='outputs/explainability_evaluation_report.md';R='outputs/robustness_evaluation_report.md';B='outputs/stabilization_report.md';D='docs/context/sources/Trustworthy-AI-Framework-Proposal_new.docx'
add('Protocol','Care este concluzia principală? Ce model câștigă?', 'Boosting are AUC și AP mai mari, dar logistica este mai stabilă în scenariul semantic. Fairness depinde de indicator. Alegerea necesită costuri și toleranțe explicite, deci nu declarăm un câștigător general.', 'Comparăm două modele fixe pe un benchmark public, pe patru dimensiuni. Rankingul, erorile la prag, explicațiile și sensibilitatea răspund la întrebări diferite. Cadrul extins rămâne propunere. Nu avem o funcție de utilitate bancară care să transforme toate dimensiunile într-un verdict unic.', 'Study & sources și cele patru secțiuni',P,True,'winner conclusion best model trade-off')
add('Protocol','Ce date folosim și ce înseamnă default?', '30.000 de înregistrări din UCI Taiwan, despre carduri de credit. Targetul este default în luna următoare. Holdout-ul are 5.996 de înregistrări, dintre care 1.320 cu default.', '22 de predictori: LIMIT_BAL, AGE, facturi, plăți, stări de rambursare, EDUCATION și MARRIAGE. ID, SEX și targetul rămân metadate. Nu presupunem că eticheta benchmarkului este identică unei definiții bancare românești. Aplicarea pe date locale cere un protocol nou.', 'Study & sources → Data and validation',B,False,'dataset label Taiwan UCI Romanian target')
add('Protocol','Ce am reparat în împărțirea train / holdout?', 'Unele rânduri aveau exact aceiași 22 de predictori în ambele seturi. Am păstrat toate rândurile și am mutat 34 de atribuiri, astfel încât fiecare grup de predictori identici să rămână într-un singur set.', 'Pornim de la split stratificat 80/20, seed 42. Grupul urmează partiția originală a membrului cu cel mai mic ID. Rezultatul: 24.004 training / 5.996 holdout, fără suprapunere exactă. Grupurile pot avea SEX sau outcome diferite. Predictorii identici nu dovedesc aceeași persoană și gruparea nu garantează eliminarea tuturor formelor de dependență.', 'Study & sources → Data and validation',B,True,'leakage duplicates overlap split repair 34 24004 5996')
add('Protocol','Holdout-ul este complet nevăzut?', 'Nu istoric. Fusese inspectat în dezvoltarea inițială. Ulterior am blocat modelele și protocolul pentru analizele următoare și declarăm această limitare.', 'Blocarea prospectivă interzice ajustări pe baza holdout-ului, dar nu șterge explorarea anterioară. Rezultatele descriu benchmarkul și designul actual. O confirmare mai puternică ar necesita date suplimentare rezervate sau validare externă adecvată.', 'Performance → nota despre holdout; Study & sources',P,True,'unseen test set inspected locked confirmatory')
add('Protocol','Ce modele și ce preprocesare avem?', 'LogisticRegression și sklearn GradientBoostingClassifier, cu pipeline-uri salvate. StandardScaler pentru variabile numerice și OneHotEncoder pentru categorii. Aceleași 22 de intrări.', 'LR: max_iter=2000, random_state=42. GBM: setările sklearn existente, random_state=42. EDUCATION 0/5/6 devin 4, MARRIAGE 0 devine 3. Pipeline-urile sunt fixe. Nu revendicăm optimizarea tuturor configurațiilor posibile.', 'Study & sources → Frozen comparison',B,False,'hyperparameters tuning scaler encoding LR GBM logistic regression gradient boosting')
add('Protocol','Holdout versus Training CV: ce schimbă selectorul?', 'Holdout evaluează modelele finale fixe pe cele 5.996 de rânduri. Training CV arată media a cinci evaluări făcute exclusiv în training, cu modele temporare.', 'StratifiedGroupKFold, 5 folduri, shuffle=True, seed 42. Predictorii identici stau împreună. Inclusiv preprocesarea se învață în fiecare fold numai din partea de antrenare. OOF: fiecare rând primește predicție când este în afara fitului respectiv. Media și SD între folduri nu sunt metrici pe predicții pooled și nici IC95%. Modelele finale nu se înlocuiesc.', 'Performance → Evaluation sample',P,True,'cross validation CV OOF folds standard deviation SD holdout')
add('Protocol','De ce pragul 0,50? Putem să-l coborâm?', '0,50 este regula comună de referință, nu un prag bancar optim. Coborârea lui poate detecta mai multe default-uri, dar produce de regulă și mai multe alarme false.', 'Regula exactă: p(default)>0,50, egalitatea este clasa 0. Candidații de prag în training OOF și sweep-ul fairness exploratoriu nu au selectat un prag nou. O schimbare cere costuri explicite și selecție numai în training, urmată de evaluare conform unui protocol autorizat.', 'Performance → confusion matrices și nota de prag',P,True,'threshold operating point 0.5 50 recall costs tuning')
add('Performance','Cum avem 81,8% accuracy, dar doar 35% recall?', 'Majoritatea înregistrărilor nu au default. Modelul poate clasifica bine această majoritate și totuși să rateze multe default-uri. Recall privește exclusiv default-urile reale.', 'Accuracy=(TP+TN)/N. Recall=TP/(TP+FN). LR detectează 468 din 1.320 default-uri, GBM 464. Un model care ar spune mereu fără default ar avea aproximativ 78% accuracy și 0% recall. Accuracy singură ascunde performanța pe clasa de interes.', 'Performance → Accuracy, Default recall și confusion matrices',P,True,'accuracy imbalance majority baseline recall 82 35 65')
add('Performance','Ce înseamnă ROC-AUC 0,757 / 0,778?', 'Măsoară cât de bine sunt ordonate cazurile cu și fără default după scorul de risc. Boosting are estimarea mai mare pe acest set.', 'AUC este probabilitatea ca un default ales aleatoriu să primească scor mai mare decât un non-default, cu jumătate de credit pentru egalități. 0,5 corespunde rankingului aleatoriu, 1 separării perfecte. Nu este procentul de clienți clasificați corect, nu arată calibrarea și nu depinde de pragul nostru 0,50.', 'Performance → Metric: ROC-AUC',P,True,'discrimination ranking AUROC ROC AUC calibration')
add('Performance','Ce este Average Precision? Este PR-AUC?', 'AP rezumă precizia pe parcursul recuperării default-urilor la praguri diferite. Folosim sklearn average_precision_score, nu integrarea trapezoidală a curbei precision–recall.', 'AP=Σ(R_n−R_(n−1))P_n la pragurile din scoruri. LR 0,5270, GBM 0,5521. AP depinde de prevalența clasei pozitive, deci comparațiile între populații cer atenție. Nu înseamnă 55% accuracy și nu este precision la pragul 0,50.', 'Performance → Metric: Average precision',P,True,'AP PR AUC precision recall average_precision_score')
add('Performance','Precision, recall, specificity și confusion matrix?', 'Recall: câte default-uri detectăm. Precision: câte flaguri sunt default-uri reale. Specificity: câte non-default-uri nu sunt flaguite. Au numitori diferiți.', 'TP: default flaguit, FN: default ratat, FP: non-default flaguit, TN: non-default neflaguit. Precision=TP/(TP+FP), specificity=TN/(TN+FP), FPR=1−specificity, FNR=1−recall. LR: TN 4.437, FP 239, FN 852, TP 468. GBM: 4.439 / 237 / 856 / 464. Precision circa 66,2% ambele. Balanced accuracy=(recall+specificity)/2. F1 este media armonică precision–recall.', 'Performance → Default precision / Specificity și confusion matrices',P,False,'TP FP FN TN precision specificity FPR FNR balanced accuracy F1')
add('Performance','Brier score și log loss: ce măsoară?', 'Verifică probabilitățile, nu doar clasificarea. Brier măsoară eroarea pătratică față de outcome. Log loss penalizează puternic predicțiile greșite foarte sigure. Mai mic este mai bine.', 'Brier=mean((p−y)²). Log loss=−mean[y ln(p)+(1−y)ln(1−p)], cu clippingul numeric sklearn. LR / GBM: Brier 0,1382 / 0,1350, log loss 0,4409 / 0,4301. Scorurile reflectă calitatea generală a probabilităților, inclusiv discriminarea, nu sunt teste pure de calibrare.', 'Performance → Brier score / Log loss',P,False,'probability loss Brier logarithm logloss formula')
add('Performance','Ce înseamnă calibrare și ECE?', 'Dacă modelul estimează un risc de circa 20% pentru multe cazuri, verificăm dacă aproximativ 20% au default. ECE rezumă abaterile dintre probabilități și frecvențe pe intervale.', '10 intervale egale pe [0,1]. ECE=Σ(n_b/N)|mean(p_b)−mean(y_b)|. Holdout LR 0,0140, GBM 0,0107, adică circa 1,40 / 1,07 pp abatere ponderată la acest binning. ECE depinde de discretizare și eșantion. Citim curbele cu numărul de rânduri pe bin. Media p apropiată de rata globală nu garantează calibrare la fiecare nivel. Nu am fitat un calibrator.', 'Performance → panoul Calibration',P,True,'ECE expected calibration error reliability bins Brier recalibration')
add('Performance','Boosting este semnificativ statistic mai bun?', 'Are estimări AUC/AP mai mari și le depășește în toate cinci foldurile. Nu am executat un test pereche al diferenței de performanță care să susțină un verdict de semnificație.', 'Intervalele marginale nu sunt intervalul diferenței. Suprapunerea lor nu înlocuiește analiza pereche. DeLong, Diebold–Mariano și MCS sunt propuse, fără execuție și fără adecvare deja validată. În robustețe avem separat intervale pereche pentru două scenarii primare.', 'Performance → ROC-AUC / AP; Robustness → comparația pereche',P,True,'significance significant hypothesis p value DeLong DM MCS paired')
add('Fairness','SEX nu intră în model. De ce mai verificăm fairness?', 'Excluderea sexului nu garantează rezultate similare între grupuri. Alte variabile pot fi asociate cu sexul, iar distribuțiile și ratele de default pot diferi.', 'SEX=1 male / 2 female, numai pentru audit. Holdout: 2.404 bărbați și 3.592 femei. Asocierile descriptive din training, inclusiv SMD și Cramér’s V, descriu relații fără a identifica proxy-uri cauzale sau discriminare. Nu avem intervenții contrafactuale sau mitigation.', 'Fairness → group results; Study & sources',F,True,'gender sex protected proxy exclusion bias SMD Cramer')
add('Fairness','Ce sunt gapurile și ce înseamnă semnul?', 'Diferențele semnate sunt femei minus bărbați. Plus la recall înseamnă detectare mai mare a default-urilor la femei. Minus la FPR înseamnă mai puține alarme false între non-default-urile feminine.', 'Recall gap LR +2,32 pp / GBM +3,35 pp. FPR gap −0,50 / −0,66 pp. pp înseamnă puncte procentuale: 36%−34%=2 pp, nu 2% relativ. Gapul SAFE absolut este unsigned. Pozitivul este flagul advers de default, nu aprobarea unui credit.', 'Fairness → Default recall gap / False-positive rate gap',F,True,'signed female minus male gap pp percentage points adverse positive')
add('Fairness','Demographic parity, equal opportunity și equalized odds?', 'Demographic parity compară rata de flagging. Equal opportunity compară recall pentru default. Equalized odds privește atât recall, cât și FPR.', 'Selection rate=P(flag=1|grup). Demographic parity difference este max−min, selection_rate_difference este semnat. Equalized odds max gap=max(|ΔTPR|,|ΔFPR|), cu ambele componente păstrate. Default observat: 23,17% male / 21,24% female. Ratele sunt ale eșantionului, nu caracteristici inerente ale grupurilor.', 'Fairness → Metric și tabelele de grup',F,False,'DP EO equal opportunity equalized odds TPR selection rate')
add('Fairness','Cum interpretăm rapoartele de grup?', 'Un raport aproape de 1 înseamnă rate observate apropiate pentru indicatorul respectiv. Trebuie citit numărătorul și numitorul.', 'Selection-rate ratio este female/male, demographic-parity ratio este min/max. Raportul flagurilor de default nu se interpretează automat ca raport de aprobări. Nu aplicăm regula 80% sau o limită legală. Prejudiciul și toleranța cer un context de decizie explicit.', 'Fairness → tabele și definiții',F,False,'ratio disparate impact DI 80 percent four fifths selection')
add('Fairness','Ce măsoară SAFE RGA și SAFE parity?', 'RGA evaluează ordonarea scorurilor în raport cu outcome-ul. SAFE parity compară RGA între grupuri, deci calitatea rankingului, nu ratele de eroare la pragul 0,50.', 'Implementarea autentică safeaipackage 0.8.3. Parity=max(RGA_grup)−min(RGA_grup). Pe acest target binar RGA coincide numeric cu AUC în toleranța verificată, fără a afirma identitate universală. Gap absolut LR 0,0079 / GBM 0,0065. Gap RGA female−male negativ LR, pozitiv GBM. RGA, RGE și RGR sunt indicatori diferiți.', 'Fairness → SAFE ranking gap; Source evidence and definitions',F,True,'SAFE RGA ranking accuracy parity max min AUC')
add('Fairness','De ce SAFE favorizează boosting, iar erorile logistica?', 'Rankingul pe întregul interval de scoruri poate fi mai apropiat între grupuri, dar erorile la un singur prag pot avea diferențe mai mari.', 'GBM are gap RGA absolut mai mic, dar gapuri absolute TPR/FPR mai mari la 0,50. Are și selection-rate gap mai mic. Sunt comparații punctuale. Fără toleranțe practice și teste între modele în etapa fairness, nu agregăm într-un verdict global.', 'Fairness → comparați Recall, FPR și SAFE',F,False,'contradiction fairness winner ranking threshold')
add('Fairness','Intervalul include zero. Înseamnă că modelul este fair?', 'Nu. Diferența semnată este compatibilă și cu zero la precizia acestei analize. Nu este o demonstrație a egalității sau echității.', 'Recall gap LR +2,32 pp, IC95% aproximativ [−2,90, 7,75] pp. Echivalența cere marjă justificată și o procedură adecvată, neimplementate. Limita inferioară a gapurilor absolute poate fi pozitivă prin construcție, deci nu inferăm semnificația din ea.', 'Fairness → intervalele gapurilor semnate',F,True,'zero confidence interval equivalence non significant fair discrimination')
add('Explainability','Ce este SHAP și în ce unități îl folosim?', 'SHAP împarte scorul unei predicții în contribuții ale variabilelor față de o referință. Plus crește scorul de default, minus îl reduce. Contribuțiile sunt în log-odds.', 'Base value + ΣSHAP_j = decision_function(X). Probabilitatea=sigmoid(scor)=1/(1+exp(−scor)). SHAP 0,2 nu înseamnă automat +20 pp probabilitate. Referința definește comparația. SHAP descrie modelul, nu cauzele default-ului.', 'Explainability → Global sau Local case',E,True,'SHAP shapley log odds logodds sigmoid probability base value causal')
add('Explainability','De ce background 100 și două explainere?', 'Folosim aceeași referință din training pentru ambele modele. LinearExplainer corespunde structurii logistice, TreeExplainer structurii de arbori.', 'SHAP 0.51.0. Background: 100 rânduri training, selecție uniformă fără înlocuire, default_rng(42), training sortat după ID, fără stratificare SEX/outcome. LinearExplainer cu Independent masker; TreeExplainer interventional, model_output=raw. Explicăm toate cele 5.996 de rânduri holdout. 100 este alegere fixă de referință și cost, nu dovadă de stabilitate față de orice background. Maskingul independent poate rupe corelații.', 'Explainability → definiții; raportul sursă',E,False,'background masker interventional linear tree correlation seed 100')
add('Explainability','22 de predictori sau 85 de coloane SHAP?', 'One-hot encoding transformă cele 22 de intrări în 85 de coloane. SHAP se calculează pe acestea, apoi contribuțiile semnate ale categoriilor se însumează înapoi la predictorul original.', 'Însumăm înainte de calculul valorii absolute, păstrând additivitatea. Pentru boosting este agregarea encoded-feature SHAP, nu un joc de coaliții recalculat separat pe 22 de variabile brute. Maskingul poate genera combinații one-hot nevalide. Limitele sunt documentate.', 'Explainability → Global; Source evidence and definitions',E,False,'one hot encoded aggregation 22 85 original features coalition')
add('Explainability','Ce înseamnă 54,2% versus 40,9%?', 'Ponderea celor mai importante trei variabile în totalul importanței SHAP a fiecărui model. Logistica are contribuțiile mai concentrate în primele trei.', 'Importanță globală j=mean(|SHAP_j|). Ponderea împarte această medie la totalul pentru cele 22 de variabile. Top 3 LR: PAY_0, LIMIT_BAL, PAY_6. GBM: PAY_0, LIMIT_BAL, PAY_AMT1. Nu este explained variance, procent de predicții explicate sau pondere cauzală. Concentrarea nu dovedește singură explicații mai bune.', 'Explainability → Global, top predictors',E,True,'importance share concentration top3 54 41 explained variance PAY_0 LIMIT_BAL')
add('Explainability','Ce este SAFE RGE și cum diferă de SHAP?', 'RGE examinează efectul înlocuirii predictorilor cu referințe din training asupra rankingului. SHAP atribuie contribuții la scorurile individuale. Sunt complementare.', 'RGE autentic folosește referințe training medii/moduri, individual și pe grupuri, cu modele fixe. Înlocuirea poate rupe relațiile dintre variabile. Corelația rangurilor SHAP/RGE circa 0,918 LR / 0,927 GBM. Acordul nu reprezintă adevăr cauzal și nu garantează fiecare explicație locală.', 'Explainability → Global, comparația RGE',E,False,'SAFE RGE replacement reference ablation rank correlation')
add('Explainability','Cum am ales cazurile locale? ID 2 ce arată?', 'Cel mai mic ID din fiecare categorie TP/TN/FP/FN pentru fiecare model, apoi explicăm uniunea cu ambele. ID 2 este default real ratat de ambele.', 'Uniunea: ID 67 TP, 12 TN, 55 FP, 2 FN. ID 2: p≈0,2664 LR / 0,3869 GBM, sub prag. Regula fixă evită alegerea unor explicații spectaculoase. Cazurile sunt ilustrative, nu reprezentative și nu dovedesc superioritatea modelului.', 'Explainability → Local case → ID 2',E,False,'local case waterfall false negative ID2 cherry picking selection')
add('Explainability','SHAP pe SEX demonstrează discriminare?', 'Nu. Arată diferențe descriptive ale contribuțiilor și importanței variabilelor între grupurile acestui eșantion.', 'Corelații ale rangurilor male/female circa 0,986 LR / 0,985 GBM. Importance shares sunt normalizate în model și grup. Distribuțiile predictorilor/scorurilor pot explica diferențe. Nu avem formal KS/Gini din brief, intervale pentru explicații sau un design cauzal.', 'Explainability → Group comparison',E,False,'group SHAP gender sex disparity Gini KS discrimination')
add('Robustness','Ce înseamnă robustness în experimentul nostru?', 'Modelele rămân fixe. Modificăm sintetic intrările și măsurăm schimbările scorurilor, rankingului, flagurilor și performanței față de outcome-ul observat.', 'Outcome-ul rămâne fix. Testăm sensibilitatea la coruperea informației, nu efectul cauzal al schimbării comportamentului unui client. Nu măsurăm frecvențe reale de erori, securitate adversarială sau fiabilitate viitoare. SAFE și semantic sunt mecanisme diferite.', 'Robustness → What this measures și Scenario identity',R,True,'stress sensitivity perturbation corruption fixed labels counterfactual')
add('Robustness','SAFE p=0,05: de ce expunere 65%?', 'p indică fracția fiecărei cozi folosite la schimburile dintre extreme, nu o modificare de 5% a valorilor. Reuniunea rândurilor afectate pe toate variabilele poate fi mult mai mare.', 'N=5.996: p=0,05 are 598 participări nominale per variabilă, circa 10%, iar ties pot reduce schimbările efective. Extremele diferă între variabile. Joint schimbă 3.906 rânduri, 65,14%. Schimburile păstrează marginalele, dar pot rupe relații și plauzibilitatea rândului. Cozile folosesc holdout-ul, conform operației native SAFE.', 'Robustness → SAFE, all features, severity 0.05',R,True,'tail swap p 5 65 exposure union opposite tails marginal')
add('Robustness','Ce face semantic q=0,10?', 'Selectăm 599 din 5.996 de rânduri și aplicăm modificări adaptate variabilelor, folosind referințe din training. Avem 30 de realizări aleatoare comune modelelor.', 'Bani: ±0,10 din IQR training, nu ±10% din valoarea clientului. AGE: ±1 an. Stări pozitive de întârziere: ±1 lună numai cu destinație suportată în training. −2/−1/0 rămân fixe. Categorii: frecvențe training condiționate pe altă categorie. Joint are o mască comună de rânduri. q=0,20 crește selecția și magnitudinea, deci este stres combinat.', 'Robustness → Semantic, all features, primary severity; Scenario identity',R,True,'q semantic IQR age delay categorical special states 599 30 repetitions')
add('Robustness','Ce limite au modificările semantice?', 'Sunt reguli de sensibilitate adaptate tipului variabilei, nu un model validat al erorilor bancare. Cazurile în care modificarea nu se poate aplica sunt raportate.', 'Plăți: minim 0. Limită credit: minim suport training. AGE: limite training. Facturile pot fi negative. Maximele monetare nu sunt plafonate. Rotunjim după precizia training. Destinațiile neacceptate și stările speciale nu sunt forțate. Parametrii și frecvențele provin din training. Nu pretindem plauzibilitate completă a clientului modificat.', 'Robustness → Scenario identity / exposure; protocol sursă',R,False,'clipping bounds rounding support eligibility no op realistic plausibility')
add('Robustness','Ce este RGR? Este Spearman?', 'RGR măsoară păstrarea ordonării folosind magnitudinile scorurilor originale și ordinea după corupere. Nu este simpla corelație Spearman.', 'SAFE apelează core.rga(probabilități originale, perturbate). Folosește min ranks, medii ale scorurilor originale la ties pe scorul perturbat și normalizare între ordonări extreme ale magnitudinilor originale. Ordine păstrată: 1; inversată: 0 în fixture-urile definite. Normalizarea este specifică modelului. Joint SAFE: 0,817 LR / 0,827 GBM. Numai puncte, fără IC.', 'Robustness → Authentic SAFE RGR, Overall',R,True,'SAFE RGR Spearman normalization ranking ties point estimates')
add('Robustness','De ce semantic RGR este N/A și RGR numai Overall?', 'Eticheta RGR este rezervată apelurilor autentice SAFE. Pentru semantic raportăm mișcare, Spearman, flips și modificările metricilor.', 'N/A nu este zero. Explorerul raportează RGR overall. Analizele SEX sunt subsetări ale coruperii globale, fără reformarea cozilor pe grup. Nu inventăm valori RGR de grup sau semantic.', 'Robustness → RGR, Layer și Group',R,False,'N A unavailable missing semantic overall male female RGR')
add('Robustness','Mean |Δp| și flag flips: cum se citesc?', 'Mean |Δp| este schimbarea absolută medie a probabilității. Flag flips este proporția care trece de partea cealaltă a pragului de 0,50.', 'Mean |Δp|=mean(|p_pert−p_base|) pe toate cele 5.996 de rânduri. 0,00827=0,827 pp, nu creștere relativă. Semantic LR / GBM: 0,51 / 0,83 pp și 0,79% / 1,30% flips. Flips poate include corectări și agravări, nu numai erori noi. Media numai pe rândurile schimbate are alt numitor și este salvată separat.', 'Robustness → Mean absolute probability movement / Flag flip rate',R,True,'movement delta probability pp flips denominator all records changed only')
add('Robustness','Cum citim ΔAUC, ΔAP, ΔBrier și GBM−LR?', 'Delta=perturbed−baseline. AUC/AP în scădere: negativ și nefavorabil. Brier în creștere: pozitiv și nefavorabil. Diferența pereche este GBM minus LR.', 'GBM−LR mean movement pozitiv: mișcare mai mare boosting. GBM−LR delta_AP negativ: degradare mai mare boosting. Semnul trebuie interpretat pe fiecare metrică. La semantic calculăm metricile separat pentru fiecare realizare și apoi mediem.', 'Robustness → metricile delta și comparația pereche',R,False,'delta perturbed baseline GBM minus LR Brier AP AUC sign')
add('Robustness','Putem spune că logistica e mai robustă?', 'În semantic primar, logistica are mișcare și flip rate mai mici, susținute de intervalele condiționate ale diferențelor. Nu este superioritate universală.', 'Semantic GBM−LR mean movement=0,00318, IC95% [0,00297,0,00340], adică 0,318 pp [0,297,0,340]. Joint SAFE: IC diferenței mișcării include zero, deși RGR punctual este mai mare GBM. Nu toate IC SAFE sunt inconcludente: diferența delta_AP are IC sub zero. Citim fiecare metrică. Mecanismele nu au stres echivalent.', 'Robustness → scenariile joint primare și Paired GBM minus LR',R,True,'robustness winner conditional significance paired semantic SAFE AP')
add('Robustness','Câte scenarii și de ce 30 de repetări?', '167 de scenarii și 1.501 realizări salvate. Repetările semantice arată variația datorată alegerilor aleatoare de corupere.', 'SAFE: (22 variabile+8 grupuri)×4 niveluri=120, plus 1 diagnostic ordine. Semantic: (22+all features)×2=46, fiecare cu 30 realizări=1.380. Total realizări 121+1.380=1.501. Explorer: 166 canonice, diagnosticul sub joint SAFE primar. 30 de repetări nu sunt 30 de populații noi.', 'Robustness → scope/severity; Study & sources',R,False,'167 166 1501 realizations Monte Carlo scenarios grid')
add('Robustness','De ce contează ordinea rândurilor în SAFE?', 'Cu valori egale, sortarea stabilă poate selecta alți membri ai cozilor după reordonare. Ordinea canonică rămâne primară, permutarea este diagnostic separat.', 'Joint SAFE p=0,05, seed 20261008: permutare comună modelelor, realiniată la ID. 1.225 de rânduri diferă ca apartenență la reuniunea expusă. Nu alegem ordinea care avantajează modelul. Diagnosticăm sensibilitatea implementării la ties.', 'Robustness → primary joint SAFE → Row-order diagnostic',R,False,'row order ties stable sorting permutation 1225 canonical')
add('Uncertainty','Cum construim intervalele bootstrap?', 'Reextragem cu înlocuire grupuri întregi de predictori identici, de 2.000 de ori, și recalculăm indicatorul. Limitele sunt percentilele 2,5 și 97,5.', 'Seed 42. Membrii grupului rămân împreună inclusiv când SEX/outcome diferă. Modelele au aceleași draws, păstrând comparația pereche. Compoziția SEX variază în resample-uri. Nu împărțim grupurile pentru stratificare. Condiționăm pe gruparea observată și modele fixe.', 'Performance/Fairness → intervale; Robustness → sampling',P,True,'bootstrap resampling confidence CI percentile groups dependence sampling 2000')
add('Uncertainty','Ce acoperă și ce nu acoperă intervalele?', 'Variația prin reeşantionarea datelor observate, cu modele fixe. În robustețe condiționăm și pe coruperile salvate.', 'Nu reantrenăm modelele și nu reformăm cozile SAFE în bootstrap. Nu estimăm variabilitatea întregii antrenări sau a unei proceduri SAFE noi pe alte date. Nu includ drift viitor ori incertitudinea unei populații românești. 95% descrie procedura de interval, nu o garanție de performanță viitoare.', 'Study & sources → Uncertainty and limits',R,True,'conditional fixed model tails training uncertainty coverage future population')
add('Uncertainty','SD, Monte Carlo și IC95% sunt același lucru?', 'Nu. SD între folduri descrie variația CV. SD între 30 de coruperi descrie variația Monte Carlo. IC bootstrap descrie incertitudinea prin reeşantionarea datelor.', 'Semantic mean movement MC SD LR 0,00040 / GBM 0,00054 =0,040 / 0,054 pp. Nu sunt standard errors sau limite IC95%. Metricile neliniare se recalculează pe fiecare realizare în resample, apoi se mediază. Nu mediem probabilități înainte de AUC/AP și nu numărăm realizările ca noi clienți.', 'Performance → Training CV; Robustness → semantic spread / sampling',R,True,'MC SD standard deviation standard error confidence interval fold variability')
add('Uncertainty','Aleatoric, epistemic și conformal: le avem?', 'Avem calibrare descriptivă și intervale condiționate pentru indicatori. Decompoziția aleatorică/epistemică și conformal prediction nu sunt implementate.', 'Aleatoric: variația inerentă outcome-ului în condițiile informației. Epistemic: incertitudinea cunoașterii/modelului. Conformal: seturi de predicție cu proprietăți de acoperire sub condițiile metodei. Nu rezultă automat din bootstrap-ul metricilor. În PPT sunt propuse, cu status pending.', 'Performance → Calibration; slide-uri 7–8 și anexa 10',D,True,'aleatoric epistemic conformal prediction uncertainty calibration fifth axis')
add('Framework & evidence','Ce este extra față de SAFE? Este nou?', 'Completăm indicatorii nativi ai pachetului cu validare, metrici convenționale, calibrare, explicații și stres semantic. Nu afirmăm că toate lipsesc din literatura SAFE/KAIRI sau că inventăm statistici noi.', 'KAIRI include deja AUC și SHAP. Pachetul și articolul nu sunt aceeași listă de metode. Nu avem replicarea formală SHAP Gini/KS din brief. Contribuția actuală este comparația empirică documentată. Noutatea cadrului și maparea regulatorie nu sunt validate.', 'Study & sources → Methodological references; slide-uri 7–8',D,True,'novelty innovation extra SAFE KAIRI package paper contribution')
add('Framework & evidence','Ce sunt DM, DeLong, KS, MCS, AOPC?', 'Metode propuse pentru întrebări diferite, nu o listă executată. Adecvarea depinde de estimand și dependența din date.', 'Orientativ: DeLong compară AUC-uri corelate; DM diferențe de pierdere predictivă sub ipoteze adecvate; KS distribuții; MCS un set de modele compatibile cu performanța conform procedurii; AOPC schimbarea outputului la eliminarea succesivă a intrărilor importante. Nu avem execuțiile sau o baterie formal validată și nu alegem testul doar după numele scorului.', 'Slide 8 și anexa 10; propunerea colegului',D,False,'Diebold Mariano DeLong Kolmogorov Smirnov KS Model Confidence Set MCS AOPC tests')
add('Framework & evidence','PSI, monitoring, mitigation și governance sunt gata?', 'Nu. Cele patru etape empirice sunt complete în scopul stabilit. PSI, monitorizarea, mitigation și guvernanța operațională rămân deschise.', 'PSI pe un train/test random nu demonstrează stabilitate temporală. Pentru drift trebuie date și perioade relevante. Nu avem date românești livrate sau validare externă. Maparea EU AI Act/NIST/HLEG este propunere, nu certificare. Extinderea este amânată până la feedbackul profesorului.', 'Study & sources → Still open',D,False,'PSI stability drift temporal monitoring mitigation governance compliance EU AI Act NIST HLEG')
add('Framework & evidence','Explorerul citește baza de date? Este hardcoded?', 'Snapshot offline generat automat din tabele salvate. Deschiderea și schimbarea selectorilor nu accesează o bază de date și nu rulează modele.', 'Datele sunt încorporate în HTML. build_explorer.py citește CSV/protocol/verification pentru a reconstrui snapshotul. Registrul identifică 28 de surse. Exportul CSV salvează tabelul afișat. Valorile nu sunt introduse manual, dar nu se actualizează live la modificarea unui CSV.', 'Study & sources → Embedded source registry; Download displayed table','explorer/README.md',False,'database hardcoded embedded snapshot offline build explorer CSV refresh')
add('Framework & evidence','SHA-256 și 30 de teste ce dovedesc?', 'Hashurile identifică versiunea exactă a fișierelor. Testele și rerulările verifică implementarea și reproducibilitatea, fără a valida automat ipotezele științifice.', 'Verificarea salvată a robusteții: 30 de teste, 24 CSV-uri și cache identice în două execuții complete. Manifestele păstrează surse, versiuni și artefacte protejate. SHA-256 nu este criptare, parolă sau dovadă a corectitudinii metodologiei. Reproducibilitatea nu dovedește validitate externă.', 'Source evidence and definitions; Study & sources → Completed evidence',R,False,'hash SHA256 reproducibility verification tests 30 24 cache manifest')
add('Framework & evidence','Ce răspund dacă întrebarea depășește analiza?', '«Nu am implementat sau validat această parte încă. Pot spune ce avem măsurat și ce ar necesita o analiză separată.»', 'Răspunde: rezultat → procedură → limită. Nu inventa p-value, garanție sau prag de fairness. Pentru setări precise deschide protocolul/raportul. La o extensie propusă de profesor, notează estimandul, ipotezele și datele necesare înainte de a promite execuția.', 'Study & sources și sursele fiecărei secțiuni',P,False,'unknown question defense limitation answer professor')

sections=list(dict.fromkeys(q['section'] for q in Q))
